/bin/bash -lc "node --input-type=module <<'JS'
import {readFileSync} from 'node:fs'
const data=JSON.parse(readFileSync('visits/e08f5bcb-979b-43d8-8e35-bf8fa6f99b6d.json'))
console.log({error:data.error, completed:data.actions.length, requested:data.requested.length})
for (const {action,state} of data.timeline){
  const lines=state.page.split('\\n')
  const diagnostics=action.target==='text=Read diagnostics' ? JSON.parse(lines.at(-1)):undefined
  console.log(state.width,action.target??action.op, lines.slice(2,-1).join(' / '), diagnostics?JSON.stringify(diagnostics):'')
}
JS
nl -ba dist/view.mjs
nl -ba dist/boot.mjs"

/bin/bash -lc "node --input-type=module <<'JS'
import {readFileSync} from 'node:fs'
const d=JSON.parse(readFileSync('visits/e08f5bcb-979b-43d8-8e35-bf8fa6f99b6d.json'))
for (const [index,{action,state}] of d.timeline.entries()){
  const page=state.page.split('\\n').slice(2).join(' / ')
  const i=page.indexOf('{\"links\":')
  console.log(index,state.width,action.target??action.op,i<0?page:page.slice(0,i),action.target==='text=Read diagnostics'?page.slice(i):'')
}
JS"

